Object.assign(SNIP,{});PRESET_NOTES["l27"]={"Ví dụ: Thêm vào cuối, lấy ra ở đầu": "Bên trái là đầu (front), bên phải là cuối (back). Phần tử ra theo đúng thứ tự vào: 1 4 5 (số 3 đã ra trước đó). So với ngăn xếp ở Bài 26: cùng chuỗi thao tác nhưng thứ tự ra ngược lại.", "Ví dụ: Bài toán Josephus với n = 7, k = 3": "Đầu hàng đợi là người sắp được đếm. Hai người đầu được đưa xuống cuối, người thứ ba bị loại. Thứ tự loại: 3 6 2 7 5 1 4; người còn lại cuối cùng là 4.", "Ví dụ: Hàng đợi hai đầu": "push_front thêm vào bên trái, push_back thêm vào bên phải; pop_front, pop_back bỏ ở hai đầu tương ứng. Mọi thao tác ở hai đầu đều O(1).", "Ví dụ: Hàng đợi vòng tự cài bằng mảng": "Theo dõi dau và cuoi: khi cuoi chạm 4 thì quay về 0, số 9 được ghi vào ô 0 vừa được giải phóng. Ô nằm ngoài đoạn dau … cuoi là rác, dù vẫn còn số cũ.", "Lỗi: hàng đợi vòng quên quay vòng": "Hàng đợi chỉ chứa 3 phần tử cùng lúc nhưng cuoi cứ tăng mãi; tới phần tử thứ năm thì ghi vào q[4], ra ngoài mảng 4 ô. Trình mô phỏng dừng và báo; trên máy thật, lỗi này có thể ghi đè lên biến khác mà không báo gì."};EX_HINTS["l27"]=[["Ban đầu đưa 1, 2, …, n vào hàng đợi theo thứ tự.", "Mỗi lượt: lặp k − 1 lần “lấy người ở đầu, đưa xuống cuối”, rồi người đang ở đầu bị loại.", "k có thể lớn hơn số người còn lại: cứ quay vòng, hàng đợi tự lo việc đó."], ["Đọc tên lệnh trước; chỉ hai lệnh PUSH có thêm số x phía sau.", "Mọi thao tác ở hai đầu của deque đều O(1). Kiểm tra rỗng trước khi POP, FRONT, BACK.", "Dùng vector với insert(begin(), x) cũng ra đúng nhưng mỗi lần thêm vào đầu tốn O(n)."], ["Các thời điểm tăng dần, nên thời điểm nào đã quá cũ với t thì cũng quá cũ với mọi yêu cầu sau: bỏ hẳn khỏi hàng đợi được.", "Mỗi thời điểm vào hàng đợi một lần, ra nhiều nhất một lần: tổng O(n).", "Đếm lại từ đầu cho mỗi yêu cầu tốn O(n²)."]];
/* ===================== BÀI 27 · Hàng đợi (queue) và hàng đợi hai đầu (deque) ===================== */
/* Bài 27 · Hàng đợi (queue) và hàng đợi hai đầu (deque)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR27=[{label:"Ví dụ: Thêm vào cuối, lấy ra ở đầu",input:"",code:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nint main() {\n    queue<int> q;\n    q.push(3);\n    q.push(1);\n    q.push(4);\n    cout << \"dau: \" << q.front() << \", cuoi: \" << q.back() << \"\\n\";\n    q.pop();\n    q.push(5);\n    while (!q.empty()) {\n        cout << q.front() << \" \";\n        q.pop();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nq = deque()\nq.append(3)\nq.append(1)\nq.append(4)\nprint(\"dau:\", q[0], \", cuoi:\", q[-1])\nq.popleft()\nq.append(5)\nwhile q:\n    print(q.popleft(), end=\" \")\nprint()",viz:[{type:"cont",of:"q",as:"queue"}],note:"deque dùng làm hàng đợi: append thêm vào cuối (bên phải), popleft lấy ra ở đầu (bên trái). Phần tử ra theo đúng thứ tự vào: 1 4 5."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        Queue<int> q = new Queue<int>();\n        q.Enqueue(3);\n        q.Enqueue(1);\n        q.Enqueue(4);\n        Console.WriteLine(\"dau: \" + q.Peek());\n        q.Dequeue();\n        q.Enqueue(5);\n        while (q.Count > 0)\n        {\n            Console.Write(q.Dequeue() + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"q",as:"queue"}],note:"Enqueue thêm vào cuối (bên phải), Dequeue lấy ra ở đầu (bên trái) và trả về phần tử đó, Peek chỉ xem. Phần tử ra theo đúng thứ tự vào: 1 4 5."}},{label:"Ví dụ: Bài toán Josephus với n = 7, k = 3",input:"",code:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n = 7, k = 3;\n    queue<int> q;\n    for (int i = 1; i <= n; i++) q.push(i);\n    while (!q.empty()) {\n        for (int j = 1; j < k; j++) {   // k - 1 người được đếm qua: đưa xuống cuối\n            q.push(q.front());\n            q.pop();\n        }\n        cout << q.front() << \" \";       // người thứ k bị loại\n        q.pop();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nn, k = 7, 3\nq = deque(range(1, n + 1))\nwhile q:\n    for _ in range(k - 1):     # k - 1 người được đếm qua: đưa xuống cuối\n        q.append(q.popleft())\n    print(q.popleft(), end=\" \")  # người thứ k bị loại\nprint()",viz:[{type:"cont",of:"q",as:"queue"}],note:"Đầu hàng đợi là người sắp được đếm. Hai người đầu được đưa xuống cuối, người thứ ba bị loại. Thứ tự loại: 3 6 2 7 5 1 4. (deque còn có q.rotate(-(k - 1)) làm đúng việc của vòng for bên trong.)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 7, k = 3;\n        Queue<int> q = new Queue<int>();\n        for (int i = 1; i <= n; i++) q.Enqueue(i);\n        while (q.Count > 0)\n        {\n            for (int j = 1; j < k; j++)       // k - 1 người được đếm qua: đưa xuống cuối\n            {\n                q.Enqueue(q.Dequeue());\n            }\n            Console.Write(q.Dequeue() + \" \");  // người thứ k bị loại\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"q",as:"queue"}]}},{label:"Ví dụ: Hàng đợi hai đầu",input:"",code:"#include <iostream>\n#include <deque>\n#include <string>\nusing namespace std;\n\nint main() {\n    deque<int> d;\n    d.push_back(1);\n    d.push_back(2);\n    d.push_front(0);\n    d.push_front(-1);\n    cout << d.front() << \" \" << d.back() << \"\\n\";\n    d.pop_front();\n    d.pop_back();\n    for (int x : d) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"d"}],py:{code:"from collections import deque\n\nd = deque()\nd.append(1)\nd.append(2)\nd.appendleft(0)\nd.appendleft(-1)\nprint(d[0], d[-1])\nd.popleft()\nd.pop()\nprint(*d)",viz:[{type:"cont",of:"d",as:"deque"}],note:"appendleft thêm vào bên trái, append thêm vào bên phải; popleft, pop bỏ ở hai đầu tương ứng. Mọi thao tác ở hai đầu đều O(1)."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        LinkedList<int> d = new LinkedList<int>();\n        d.AddLast(1);\n        d.AddLast(2);\n        d.AddFirst(0);\n        d.AddFirst(-1);\n        Console.WriteLine(d.First.Value + \" \" + d.Last.Value);\n        d.RemoveFirst();\n        d.RemoveLast();\n        foreach (int x in d) Console.Write(x + \" \");\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"d",as:"deque"}],note:"LinkedList dùng làm hàng đợi hai đầu: AddFirst thêm vào bên trái, AddLast thêm vào bên phải; RemoveFirst, RemoveLast bỏ ở hai đầu; First.Value, Last.Value xem hai đầu. Mọi thao tác ở hai đầu đều O(1)."}},{label:"Ví dụ: Hàng đợi vòng tự cài bằng mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int N = 4;\nint q[N];\nint dau = 0, cuoi = 0, dem = 0;   // dem: số phần tử đang có\n\nvoid them(int x) { q[cuoi] = x; cuoi = (cuoi + 1) % N; dem++; }\nint lay() { int x = q[dau]; dau = (dau + 1) % N; dem--; return x; }\n\nint main() {\n    them(5);\n    them(6);\n    them(7);\n    cout << lay() << \" \" << lay() << \"\\n\";\n    them(8);\n    them(9);          // ô 0 được dùng lại\n    while (dem > 0) cout << lay() << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"q",ptr:["dau","cuoi"]},{type:"vars",names:["dem"]}],py:{code:"N = 4\nq = [0] * N\ndau = cuoi = dem = 0      # dem: số phần tử đang có\n\ndef them(x):\n    global cuoi, dem\n    q[cuoi] = x\n    cuoi = (cuoi + 1) % N\n    dem += 1\n\ndef lay():\n    global dau, dem\n    x = q[dau]\n    dau = (dau + 1) % N\n    dem -= 1\n    return x\n\nthem(5)\nthem(6)\nthem(7)\nprint(lay(), lay())\nthem(8)\nthem(9)          # ô 0 được dùng lại\nwhile dem > 0:\n    print(lay(), end=\" \")\nprint()"},cs:{code:"using System;\n\nclass Program\n{\n    const int N = 4;\n    static int[] q = new int[N];\n    static int dau = 0, cuoi = 0, dem = 0;   // dem: số phần tử đang có\n\n    static void Them(int x) { q[cuoi] = x; cuoi = (cuoi + 1) % N; dem++; }\n    static int Lay() { int x = q[dau]; dau = (dau + 1) % N; dem--; return x; }\n\n    static void Main()\n    {\n        Them(5);\n        Them(6);\n        Them(7);\n        Console.WriteLine(Lay() + \" \" + Lay());\n        Them(8);\n        Them(9);          // ô 0 được dùng lại\n        while (dem > 0) Console.Write(Lay() + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Lỗi: hàng đợi vòng quên quay vòng",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int N = 4;\nint q[N];\nint dau = 0, cuoi = 0;\n\nvoid them(int x) { q[cuoi] = x; cuoi = cuoi + 1; }    // thiếu % N\nint lay() { int x = q[dau]; dau = dau + 1; return x; }\n\nint main() {\n    for (int i = 1; i <= 3; i++) them(i);\n    cout << lay() << \" \" << lay() << \"\\n\";\n    them(4);\n    them(5);          // cuoi = 4: ghi ra ngoài mảng\n    cout << lay() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"q",ptr:["dau","cuoi"]}],py:{code:"N = 4\nq = [0] * N\ndau = cuoi = 0\n\ndef them(x):\n    global cuoi\n    q[cuoi] = x\n    cuoi = cuoi + 1          # thiếu % N\n\ndef lay():\n    global dau\n    x = q[dau]\n    dau = dau + 1\n    return x\n\nfor i in range(1, 4):\n    them(i)\nprint(lay(), lay())\nthem(4)\nthem(5)          # cuoi = 4: ghi ra ngoài list\nprint(lay())",note:"Hàng đợi chỉ chứa 3 phần tử cùng lúc nhưng cuoi cứ tăng mãi; tới phần tử thứ năm thì gán q[4] cho list 4 phần tử: Python báo IndexError: list assignment index out of range."},cs:{code:"using System;\n\nclass Program\n{\n    const int N = 4;\n    static int[] q = new int[N];\n    static int dau = 0, cuoi = 0;\n\n    static void Them(int x) { q[cuoi] = x; cuoi = cuoi + 1; }    // thiếu % N\n    static int Lay() { int x = q[dau]; dau = dau + 1; return x; }\n\n    static void Main()\n    {\n        for (int i = 1; i <= 3; i++) Them(i);\n        Console.WriteLine(Lay() + \" \" + Lay());\n        Them(4);\n        Them(5);          // cuoi = 4: ghi ra ngoài mảng\n        Console.WriteLine(Lay());\n    }\n}",note:"Hàng đợi chỉ chứa 3 phần tử cùng lúc nhưng cuoi cứ tăng mãi; tới phần tử thứ năm thì ghi vào q[4] của mảng 4 ô: IndexOutOfRangeException."}}];
